Drag implementation (pointer-based):

```js
function makeSortable(ul){
  let drag = null;
  function start(e){
    const li = e.target.closest('li.disc-item');
    if(!li) return;
    if(e.pointerType === 'mouse' && e.button !== 0) return;
    e.preventDefault();
    const rect = li.getBoundingClientRect();
    drag = {li, ul, dy: e.clientY - rect.top};
    li.setPointerCapture(e.pointerId);
    li.classList.add('is-dragging');
    ul.classList.add('is-reordering');
    li.style.position = 'fixed';
    li.style.width = rect.width + 'px';
    li.style.left = rect.left + 'px';
    li.style.top = rect.top + 'px';
    li.style.margin = '0';
    li.style.zIndex = '50';
  }
  function move(e){
    if(!drag) return;
    e.preventDefault();
    const y = e.clientY;
    drag.li.style.top = (y - drag.dy) + 'px';
    const siblings = [...drag.ul.children].filter(el => el !== drag.li);
    let after = null;
    for(const s of siblings){
      const r = s.getBoundingClientRect();
      if(y < r.top + r.height/2){ after = s; break; }
    }
    drag.ul.insertBefore(drag.li, after);
  }
  function end(e){
    if(!drag) return;
    const {li, ul} = drag; drag = null;
    li.classList.remove('is-dragging');
    ul.classList.remove('is-reordering');
    li.style.cssText = '';
  }
  ul.addEventListener('pointerdown', start);
  ul.addEventListener('pointermove', move);
  ul.addEventListener('pointerup', end);
  ul.addEventListener('pointercancel', end);
}
```

Note: with setPointerCapture on li, move events are targeted at li; the ul listeners still fire via bubbling. Good.

